"""Build a portable local gallery. Character art and audition videos stay in this folder."""
import json, html
from pathlib import Path
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
concepts=json.loads((ROOT/'concepts.json').read_text());meta=json.loads((ROOT/'render-metadata.json').read_text())
materials=['Felt otter','Soft clay','Knitted cloud','Glazed porcelain','Opal & paper','Wood & folded paper','Hand-felted wool','Glazed leaf sprite','Porcelain & light','Folded cotton paper','Sculptural origami','Woven ribbon','Porcelain cloud-whale','Pearlescent ceramic','Translucent art glass','Velvet & warm light','Stone & living moss','Bamboo & porcelain','Silk & velvet','Woven ribbon knot','Felt & paper','Ceramic & paper leaves','Glazed ceramic','Folded cloth','Felt & amber']
(ROOT/'thumbs').mkdir(exist_ok=True)
for c in concepts:
 m=meta[c['id']];c['stem']=m['stem'];c['motion']=m['motion'];c['material']=materials[c['number']-1]
 im=Image.open(ROOT/'cutouts'/f"{c['stem']}.png").convert('RGBA');im.thumbnail((640,640),Image.Resampling.LANCZOS);im.save(ROOT/'thumbs'/f"{c['stem']}.webp",quality=90)
data=json.dumps(concepts,ensure_ascii=False)
page=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Round 2 · AI Peer companions</title>
<style>
@font-face{font-family:Manrope;src:url(../film/assets/fonts/Manrope.ttf);font-weight:200 800}*{box-sizing:border-box}body{margin:0;background:#f4f1e7;color:#183f31;font-family:Manrope,Arial,sans-serif}button,a{font:inherit}a{color:inherit;text-underline-offset:4px}button{cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #b57632;outline-offset:4px}header{padding:28px 5vw;border-bottom:1px solid #ced5c3;display:flex;justify-content:space-between;align-items:center}header a{text-decoration:none}.brand{font-weight:800;letter-spacing:2px;font-size:15px}.edition{font-size:13px;color:#657c67}.hero{max-width:1460px;margin:auto;display:grid;grid-template-columns:1fr 1fr;gap:26px;align-items:center;padding:65px 5vw 50px}.eyebrow{font-size:12px;letter-spacing:2.5px;font-weight:800;text-transform:uppercase;color:#6a8168}h1{font-family:Georgia,serif;font-size:clamp(45px,5.2vw,78px);font-weight:400;line-height:1.02;letter-spacing:-2.8px;margin:18px 0 26px;max-width:640px}.lede{max-width:550px;line-height:1.8;font-size:16px;color:#536e59}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.primary,.secondary{border:1px solid #254c37;border-radius:999px;padding:13px 22px;text-decoration:none;font-size:13px;font-weight:700}.primary{background:#204b36;color:#fffbed}.secondary{background:transparent;color:#214d38}.heroart{height:425px;position:relative;display:flex;align-items:center;justify-content:center;border-radius:50%;background:radial-gradient(ellipse,#e5ead6,transparent 68%)}.heroart img{position:absolute;object-fit:contain;height:95%;width:63%;filter:drop-shadow(0 16px 12px #243c2620)}.heroart img:first-child{left:-4%;height:72%;top:28%}.heroart img:nth-child(2){right:-4%;height:72%;top:28%}.heroart img:nth-child(3){left:20%;top:-3%}.heroart .note{position:absolute;bottom:-3px;text-align:center;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#789075}.context{max-width:1320px;margin:0 auto 45px;padding:20px 25px;border-top:1px solid #cbd4c1;border-bottom:1px solid #cbd4c1;display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.context b{display:block;font-size:12px;letter-spacing:.5px}.context p{margin:7px 0 0;color:#667e66;font-size:13px;line-height:1.6}main{max-width:1460px;padding:0 5vw 60px;margin:auto}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:22px}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters button{border:1px solid #c3cfb9;background:transparent;color:#56765d;border-radius:999px;padding:9px 14px;font-size:12px}.filters button.active{background:#204b36;border-color:#204b36;color:#fffbed}#count{font-size:12px;color:#789075}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.card{background:#fffcf3;border:1px solid #cdd5c1;border-radius:23px;overflow:hidden;position:relative;transition:box-shadow .2s,transform .2s}.card:hover{box-shadow:0 12px 30px #26412c10;transform:translateY(-2px)}.card-top{display:flex;align-items:center;justify-content:space-between;padding:18px 20px 0;font-size:11px;letter-spacing:1px;color:#698269}.star{border:1px solid #c9d2bc;border-radius:999px;background:transparent;color:#5b7b61;padding:6px 11px;font-size:11px;letter-spacing:0}.star.on{background:#e0ecd3;border-color:#89a87c;color:#244b32}.art{height:290px;width:100%;object-fit:contain;display:block;padding:0 10px;margin-top:-6px}.card-body{padding:4px 23px 22px}.titleline{display:flex;align-items:center;justify-content:space-between}.card h2{font-family:Georgia,serif;font-size:32px;font-weight:400;margin:0}.avatar{width:43px;height:43px;border-radius:12px}.line{height:44px;line-height:1.55;font-size:13px;color:#5a745c;margin:12px 0 16px}.watch{width:100%;border:0;background:#244e39;color:#fffbed;border-radius:11px;padding:12px 8px;font-weight:600;font-size:12px}.links{display:flex;justify-content:space-between;font-size:10px;color:#788c73;margin-top:15px}.method{font-size:10px;color:#8b967f;margin:12px 0 0}.shortlist{background:#e7eddb;border:1px solid #c3cfb6;border-radius:15px;padding:16px 20px;margin:0 0 25px;line-height:1.6;font-size:12px;display:none}.shortlist b{margin-right:10px}.shortlist span{color:#59775e}.empty{grid-column:1/-1;padding:75px;text-align:center;color:#6e866d}footer{background:#e7ebdc;padding:35px 5vw;display:flex;gap:28px;justify-content:space-between;font-size:12px;color:#60775e;line-height:1.8}footer p{margin:0;max-width:700px}dialog{padding:0;border:1px solid #708666;border-radius:18px;background:#f5f1e6;color:#173f30;width:min(1150px,95vw);max-height:95vh;box-shadow:0 30px 100px #0006}dialog::backdrop{background:#092a21cc;backdrop-filter:blur(6px)}.dialog-head{padding:16px 22px;display:flex;justify-content:space-between;align-items:center}.dialog-head h2{font-family:Georgia,serif;font-size:25px;font-weight:400;margin:0}.close{border:0;border-radius:100%;width:35px;height:35px;background:#e1e7d7;font-size:20px;color:#264b35}dialog video{display:block;width:100%;aspect-ratio:16/9;background:#0f2a23}.dialog-foot{padding:16px 22px;font-size:12px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;color:#61775d}.groups{display:flex;gap:13px;font-size:11px;flex-wrap:wrap;margin:18px 0 28px;color:#6b8369}
@media(max-width:950px){.hero{padding-top:40px}.heroart{height:320px}.grid{grid-template-columns:repeat(2,1fr)}.context{margin:0 5vw 30px}.art{height:260px}}
@media(max-width:620px){header{padding:22px 6vw}.edition{font-size:10px}.hero{grid-template-columns:1fr;padding:40px 6vw 25px}.heroart{height:300px}.heroart img{width:60%}h1{font-size:53px}.context{grid-template-columns:1fr;gap:13px;padding:20px}.grid{grid-template-columns:1fr}.art{height:320px}.card .line{height:auto}.toolbar{gap:10px}.filters button{font-size:11px;padding:8px 11px}footer{flex-direction:column;gap:14px}.dialog-head h2{font-size:20px}.groups{font-size:10px}}
</style></head><body>
<header><a class="brand" href="#">AI PEER</a><span class="edition">MASCOT EXPLORATION / ROUND 2</span></header>
<section class="hero"><div><div class="eyebrow">Twenty-five original companions</div><h1>A happier kind<br>of teammate.</h1><p class="lede">A little warmth beside your work. Explore 25 generated characters in the same room, meeting, morning brief and closing card—and save the ones you would love to have around.</p><div class="actions"><button class="primary" id="quicklook">Watch all 25 · 75 seconds</button><a class="secondary" href="#characters">Meet the companions</a></div></div><div class="heroart" aria-label="Miso, Mallow and Moss"><img src="thumbs/01-miso.webp" alt="Miso"><img src="thumbs/03-mallow.webp" alt="Mallow"><img src="thumbs/25-moss.webp" alt="Moss"><span class="note">Same cream, forest and mint world</span></div></section>
<div class="context"><div><b>One fair comparison</b><p>Every audition is 23.3 seconds, using the same four scenes and original audio.</p></div><div><b>Designed to feel alive</b><p>23 characters have generated acting. Nori and Dew use subtle composed movement to preserve their translucent materials.</p></div><div><b>Your choice comes next</b><p>These are short auditions. The approved full film is preserved; no replacement has been selected.</p></div></div>
<main id="characters"><div class="toolbar"><div class="filters"><button class="active" data-filter="all">All companions</button><button data-filter="motion">Generated motion</button><button data-filter="translucent">Translucent pair</button><button data-filter="saved">My shortlist</button></div><span id="count"></span></div><div class="shortlist" id="shortlist"></div><div class="groups"><a href="renders/overview.jpg" target="_blank">All 25 · portrait overview ↗</a><a href="renders/group-1.jpg" target="_blank">01–05 ↗</a><a href="renders/group-2.jpg" target="_blank">06–10 ↗</a><a href="renders/group-3.jpg" target="_blank">11–15 ↗</a><a href="renders/group-4.jpg" target="_blank">16–20 ↗</a><a href="renders/group-5.jpg" target="_blank">21–25 ↗</a></div><div class="grid" id="grid"></div></main>
<footer><p>Original Gemini character artwork · fal cutouts and character animation · Local scene compositing.<br>Room → meeting → morning brief → closing mark. Public demo footage only.</p><p><a href="README.md">Making the collection</a><br>16 November 2026 · Your shortlist stays in this browser.</p></footer>
<dialog id="player"><div class="dialog-head"><h2 id="video-title"></h2><button class="close" aria-label="Close preview">×</button></div><video controls playsinline preload="metadata"></video><div class="dialog-foot"><span id="video-note"></span><a id="master-link" target="_blank">Open 1080p master ↗</a></div></dialog>
<script>
const data=__DATA__;let filter='all';let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('ai-peer-round2-shortlist')||'[]'))}catch{}
const grid=document.querySelector('#grid'),dialog=document.querySelector('#player'),video=dialog.querySelector('video');
function render(){const shown=data.filter(c=>filter==='all'||filter==='motion'&&c.motion||filter==='translucent'&&!c.motion||filter==='saved'&&saved.has(c.id));document.querySelector('#count').textContent=shown.length+' companions';grid.innerHTML=shown.length?shown.map(c=>`<article class="card"><div class="card-top"><span>${String(c.number).padStart(2,'0')} · ${c.material}</span><button class="star ${saved.has(c.id)?'on':''}" data-save="${c.id}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'♥ Saved':'♡ Shortlist'}</button></div><img class="art" src="thumbs/${c.stem}.webp" alt="${c.name}, full character" loading="lazy"><div class="card-body"><div class="titleline"><h2>${c.name}</h2><img class="avatar" src="avatars/${c.stem}.png" alt="${c.name} as app icon" loading="lazy"></div><p class="line">${c.line}</p><button class="watch" data-play="${c.id}">Watch ${c.name} in the film · 23s</button><div class="links"><a href="renders/${c.stem}-encoded.jpg" target="_blank">Scene contact sheet ↗</a><a href="images/${c.stem}.png" target="_blank">Original artwork ↗</a></div><p class="method">${c.motion?'Generated character acting':'Provider-alpha still · Gentle composed movement'}</p></div></article>`).join(''):'<div class="empty">Tap ♡ Shortlist on a companion to save it here.</div>';const choices=data.filter(c=>saved.has(c.id));const bar=document.querySelector('#shortlist');bar.style.display=choices.length?'block':'none';bar.innerHTML='<b>Your shortlist</b><span>'+choices.map(c=>String(c.number).padStart(2,'0')+' '+c.name).join(' · ')+'</span>';}
function play(c){document.querySelector('#video-title').textContent=c?'Round 2 · '+String(c.number).padStart(2,'0')+' '+c.name:'Round 2 · All 25 companions';video.src='renders/'+(c?c.stem:'quick-look-75s')+'.mp4';document.querySelector('#video-note').textContent=c?(c.motion?'Generated character acting':'Gentle composed movement')+' · Original scene audio':'Three seconds with each companion · Existing instrumental bed';document.querySelector('#master-link').href='renders/'+(c?c.stem:'quick-look-75s')+'-1080p.mp4';dialog.showModal();video.play().catch(()=>{});}
grid.addEventListener('click',e=>{const save=e.target.closest('[data-save]'),watch=e.target.closest('[data-play]');if(save){const id=save.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('ai-peer-round2-shortlist',JSON.stringify([...saved]))}catch{}render();}if(watch)play(data.find(c=>c.id===watch.dataset.play));});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render();});document.querySelector('#quicklook').onclick=()=>play();dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{video.pause();video.removeAttribute('src');video.load()});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});render();
</script></body></html>'''
(ROOT/'index.html').write_text(page.replace('__DATA__',data))
print('index.html and 25 compact thumbnails ready')
